const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export type Item = {
  type: string;
};

function basePremiumOf(item: Item): number {
  if (COMPONENT_TYPES.has(item.type)) {
    return COMPONENT_BASE_PREMIUM;
  }
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

export function quote(items: Item[]): number {
  const basePremium = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  return basePremium + PROCESSING_FEE;
}
EOF
