import { describe, expect, it } from "vitest";
import { quote } from "./claim-office.js";

const NEWCOMER = { yearsWithMHPCO: 0 };

describe("MHPCO claim office", () => {
  // --- Quote: simplest case and the processing fee ---
  it("quotes an empty item list as 5 G -- only the processing fee", () => {
    expect(quote([], NEWCOMER)).toBe(5);
  });

  // --- Quote: the main item price list (each entry is independent data) ---
  it("quotes a single plain sword as 105 G -- 100 G base + 5 G fee", () => {
    expect(quote([{ type: "sword" }], NEWCOMER)).toBe(105);
  });
  it("quotes a single plain amulet as 65 G -- 60 G base + 5 G fee", () => {
    expect(quote([{ type: "amulet" }], NEWCOMER)).toBe(65);
  });
  it("quotes a single plain staff as 85 G -- 80 G base + 5 G fee", () => {
    expect(quote([{ type: "staff" }], NEWCOMER)).toBe(85);
  });
  it("quotes a single plain potion as 45 G -- 40 G base + 5 G fee", () => {
    expect(quote([{ type: "potion" }], NEWCOMER)).toBe(45);
  });

  // --- Quote: components and the building block of 3 alike ---
  it("quotes a single rune as 30 G -- 25 G base + 5 G fee", () => {
    expect(quote([{ type: "rune" }], NEWCOMER)).toBe(30);
  });
  it("quotes a single moonstone as 30 G -- 25 G base + 5 G fee", () => {
    expect(quote([{ type: "moonstone" }], NEWCOMER)).toBe(30);
  });
  it("quotes 2 runes as 55 G -- 50 G base premium, no block + 5 G fee", () => {
    expect(quote([{ type: "rune" }, { type: "rune" }], NEWCOMER)).toBe(55);
  });

  it("quotes 3 runes as 65 G -- 60 G block base premium + 5 G fee", () => {
    expect(quote([{ type: "rune" }, { type: "rune" }, { type: "rune" }], NEWCOMER)).toBe(65);
  });
  it("quotes 4 runes as 105 G -- 100 G base premium, block requires exactly 3 + 5 G fee", () => {
    expect(quote(Array.from({ length: 4 }, () => ({ type: "rune" })), NEWCOMER)).toBe(105);
  });

  it("quotes 7 runes as 180 G -- 175 G base premium + 5 G fee", () => {
    expect(quote(Array.from({ length: 7 }, () => ({ type: "rune" })), NEWCOMER)).toBe(180);
  });
  it("quotes 2 runes + 1 moonstone as 80 G -- 75 G base, no block across different types + 5 G fee", () => {
    expect(quote([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }], NEWCOMER)).toBe(80);
  });
  it("quotes 3 runes + 3 moonstones as 125 G -- 120 G base, two separate blocks + 5 G fee", () => {
    const items = [
      ...Array.from({ length: 3 }, () => ({ type: "rune" })),
      ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
    ];
    expect(quote(items, NEWCOMER)).toBe(125);
  });

  it("quotes 3 moonstones as 65 G -- the block rule applies per component type, not only to runes", () => {
    expect(quote(Array.from({ length: 3 }, () => ({ type: "moonstone" })), NEWCOMER)).toBe(65);
  });

  // --- Quote: item-specific modifiers ---
  it("adds a 50 % curse surcharge to the cursed item's base premium -- cursed sword alone is 100 + 50 + 5 = 155 G", () => {
    expect(quote([{ type: "sword", cursed: true }], NEWCOMER)).toBe(155);
  });
  it("adds a 30 % high-enchantment surcharge at enchantment 5 exactly -- sword enchantment 5 is 100 + 30 + 5 = 135 G", () => {
    expect(quote([{ type: "sword", enchantment: 5 }], NEWCOMER)).toBe(135);
  });
  it("adds no high-enchantment surcharge at enchantment 4 -- sword enchantment 4 is 105 G", () => {
    expect(quote([{ type: "sword", enchantment: 4 }], NEWCOMER)).toBe(105);
  });

  it("stacks curse and high-enchantment surcharges on the same item -- cursed sword enchantment 5 is 100 + 50 + 30 + 5 = 185 G", () => {
    expect(quote([{ type: "sword", enchantment: 5, cursed: true }], NEWCOMER)).toBe(185);
  });
  it("applies item-specific surcharges only to the affected item -- cursed sword + plain amulet is 160 + 50 + 5 = 215 G", () => {
    expect(quote([{ type: "sword", cursed: true }, { type: "amulet" }], NEWCOMER)).toBe(215);
  });

  // --- Quote: policy-wide modifiers ---
  it("applies the 20 % loyalty discount at exactly 2 years with MHPCO -- plain sword is 100 - 20 + 5 = 85 G", () => {
    expect(quote([{ type: "sword" }], { yearsWithMHPCO: 2 })).toBe(85);
  });
  it.todo("applies no loyalty discount at 1 year with MHPCO -- plain sword is 105 G");
  it.todo("applies the 10 % first-insurance surcharge -- documented reading: it applies to every quote's policy base premium, since each item in a quote is treated as a first insurance");
  it.todo("applies the 15 % follow-up discount on the customer's second quote -- plain sword second quote is 100 + 10 - 15 + 5 = 100 G");
  it.todo("applies the 15 % follow-up discount on the third quote as well -- each contract after the first");
  it.todo("computes policy-wide modifiers from the policy base premium, not from item base premiums -- sword + amulet with loyalty is 160 - 32 + 16 + 5 = 149 G");

  // --- Quote: rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G -- rounding is in the MHPCO's favour");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples from the spec ---
  it.todo("newcomer with a cursed sword (0 years, first contract) -- premium 165 G");
  it.todo("long-standing customer's second contract with a cursed sword enchantment 7 (3 years) -- premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote with an unknown item type -- documented reading: the domain throws an Error, which the CLI turns into a non-zero exit and a stderr message");

  // --- Claim: deductible and standard reimbursement ---
  it.todo("pays 400 G for a steel sword at enchantment 3 damaged 500 G -- full reimbursement minus the 100 G deductible");
  it.todo("pays 100 G for a rune damaged 200 G -- runes have no enchantment or material, so no special clause applies");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G is a payout of 600 G");
  it.todo("pays 0 G when the damage amount is below the deductible -- documented reading: a payout is never negative");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item at enchantment 8 at 50 % -- steel sword enchantment 8 damaged 1000 G pays 400 G");
  it.todo("applies no high-enchantment clause at enchantment 7 -- steel sword damaged 1000 G pays 900 G");
  it.todo("reimburses dragon material fully -- dragon sword enchantment 5 damaged 800 G pays 700 G");
  it.todo("lets the 50 % rule win over dragon material -- dragon sword enchantment 9 damaged 1000 G pays 400 G");
  it.todo("applies the 50 % rule then the deductible for a dragon sword at exactly enchantment 8 damaged 1000 G -- payout 400 G");
  it.todo("applies only the high-enchantment clause for a steel sword enchantment 9 damaged 1000 G -- payout 400 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum -- a single sword gives a cap of 2000 G");
  it.todo("sums the insurance values of all items -- sword + amulet gives an insurance sum of 1600 G and a cap of 3200 G");
  it.todo("bases the cap on unmodified insurance values -- a cursed sword still has a cap of 2000 G despite its 165 G premium");
  it.todo("counts components at 250 G in the insurance sum despite the block discount -- sword + 3 runes gives an insurance sum of 1750 G and a cap of 3500 G");
  it.todo("reports the remaining cap after a claim -- sword, claim 1500 G pays 1400 G and leaves 600 G");
  it.todo("reduces a later claim to the remaining cap -- second 1500 G claim pays 600 G and leaves 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("insures two swords as an insurance sum of 2000 G and a cap of 4000 G");
  it.todo("treats two sword damage entries as separate damages with their own deductible -- 2 entries of 500 G pay 800 G");

  // --- Claim: rounding in the MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G -- rounding is in the MHPCO's favour");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not covered by the policy -- amulet damage against a sword-only policy throws");
  it.todo("rejects a claim with an unknown damaged item type -- documented reading: same error contract as an uncovered item");
  it.todo("rejects a claim with more damage entries of a type than the policy covers -- two sword damages against one insured sword throws");
  it.todo("rejects a claim with a negative damage amount -- amount -200 throws");

  // --- CLI adapter: stdin/stdout contract ---
  it.todo("writes {results:[{premium}]} to stdout for a quote-only scenario");
  it.todo("writes {payout, remainingCap} for a claim step and resolves the policy by its zero-based step index");
  it.todo("processes steps sequentially so a claim sees the cap left by an earlier claim on the same policy");
  it.todo("exits non-zero and writes an error description to stderr, with no results on stdout, for an invalid scenario");
});

