export class ClaimOffice {
  private contractsIssued = 0;

  constructor(private readonly customer: Customer) {}

  quote(items: Item[]): number {
    const premium = premiumFor(items, this.customer, this.contractsIssued);
    this.contractsIssued += 1;
    return premium;
  }
}

